/**
 * The site gateway against the MT-SICS simulator over localhost TCP, uploading to a fake server listener.
 */
import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'vitest';
import { interpretWeightLine, readingProblem, type LiveSample } from '@ebmr/integration-sdk/scale';
import { startGatewayApi } from '../src/api.ts';
import { SiteGateway } from '../src/gateway.ts';
import { FakeServer, configFor, gatewayKeys, startSimulator, tempDir, until, type SimProcess } from './support.ts';

let sim: SimProcess;
let server: FakeServer;
let gateway: SiteGateway;
const keys = gatewayKeys();

beforeAll(async () => {
  sim = await startSimulator();
  server = new FakeServer(keys.publicKeySpki);
  await server.start();
  const config = configFor({ simPort: sim.tcpPort, uplink: server.url, journalDir: tempDir(), keys, captureTimeoutMs: 2000 });
  gateway = await SiteGateway.start(config, { driver: { commandTimeoutMs: 1000, backoffInitialMs: 100, backoffMaxMs: 400 } });
  await until(() => gateway.uplink.login !== null && gateway.instruments.get('TEST-BAL-01')?.driver.state === 'ONLINE', 15_000, 'login and connection');
}, 60_000);

afterAll(async () => {
  await gateway?.stop();
  await server?.stop();
  await sim?.stop();
});

beforeEach(async () => {
  await sim.control('reset');
  await until(() => gateway.instruments.get('TEST-BAL-01')?.driver.state === 'ONLINE', 10_000, 'the balance online');
});

const driver = () => gateway.instruments.get('TEST-BAL-01')!.driver;

describe('site gateway with the MT-SICS simulator', () => {
  it('[DI-32][DI-31] a stable capture journals, signs and uploads the reading with its raw line; the server holds it', async () => {
    await sim.control('place', { mass: '1.250' });
    const r = await gateway.capture('TEST-BAL-01', 'TARE');
    expect(r.outcome).toBe('CAPTURED');
    if (r.outcome !== 'CAPTURED') return;
    expect(r.uplinked).toBe(true);
    expect(r.reading).toMatchObject({ deviceCode: 'TEST-BAL-01', serial: 'SIM-0001', value: '1.250', unit: 'kg', stable: true, status: 'OK', purpose: 'TARE', trust: 'DEVICE_UNSYNCED', installation: 'SANDBOX' });
    expect(r.reading.raw).toBe('S S      1.250 kg');
    expect(interpretWeightLine(r.reading.raw).value).toBe(r.reading.value);
    expect(readingProblem(r.reading, gateway.config.publicKey)).toBeNull();
    expect(server.readings.at(-1)?.readingId).toBe(r.reading.readingId);
    // The acknowledgement watermark follows: the answer waits for its write only up to the capture's 5 s (decision
    // X28), so on a slow disk it can come first (delivery-readiness.test.ts proves the wait with a stalled write).
    const seq = BigInt(r.reading.seq);
    await until(() => gateway.journal.ackedSeq === seq, 10_000, 'the acknowledgement watermark written');
  });

  it('[DI-32] an unstable weight is never captured as stable: the timeout answers NOT_STABLE and records it as UNSTABLE', async () => {
    await sim.control('place', { mass: '2.000' });
    await sim.control('fault', { fault: 'UNSTABLE', on: true });
    const r = await gateway.capture('TEST-BAL-01', 'GROSS', 1500);
    expect(r.outcome).toBe('FAILED');
    if (r.outcome !== 'FAILED') return;
    expect(r.error).toBe('NOT_STABLE_WITHIN_TIMEOUT');
    expect(r.reading).toMatchObject({ stable: false, status: 'UNSTABLE' });
    expect(r.reading?.raw).toMatch(/^S D /);
    expect(server.readings.filter((x) => x.status === 'OK' && x.readingId === r.reading?.readingId)).toEqual([]);
  });

  it('overload is refused and recorded as OVERLOAD, without a value', async () => {
    await sim.control('set', { mass: '75.000' });
    const r = await gateway.capture('TEST-BAL-01', 'GROSS');
    expect(r).toMatchObject({ outcome: 'FAILED', error: 'OVERLOAD' });
    if (r.outcome === 'FAILED') expect(r.reading).toMatchObject({ value: null, status: 'OVERLOAD', raw: 'S +' });
  });

  it('[DI-31] a garbled line is rejected: nothing is recorded and the connection is re-established and re-verified', async () => {
    await sim.control('place', { mass: '1.000' });
    await new Promise((r) => setTimeout(r, 400));
    const before = gateway.journal.lastSeq();
    await sim.control('fault', { fault: 'GARBLED', on: true });
    const r = await gateway.capture('TEST-BAL-01', 'GROSS');
    expect(r).toMatchObject({ outcome: 'FAILED', error: 'PROTOCOL_ERROR' });
    expect(gateway.journal.lastSeq()).toBe(before);
    expect(gateway.alarms.some((a) => a.kind === 'PROTOCOL_ERROR')).toBe(true);
    await sim.control('fault', { fault: 'GARBLED', on: false });
    await until(() => driver().state === 'ONLINE', 10_000, 'reconnect');
    expect((await gateway.capture('TEST-BAL-01', 'GROSS')).outcome).toBe('CAPTURED');
  });

  it('offline and reconnect: an offline balance answers DEVICE_OFFLINE; it reconnects with back-off when it comes back', async () => {
    await sim.control('fault', { fault: 'OFFLINE', on: true });
    await until(() => driver().state === 'OFFLINE', 5000, 'offline');
    expect(await gateway.capture('TEST-BAL-01', 'GROSS')).toMatchObject({ outcome: 'FAILED', error: 'DEVICE_OFFLINE' });
    await until(() => server.heartbeats.at(-1)?.devices[0]?.state === 'OFFLINE', 5000, 'an OFFLINE heartbeat');
    await sim.control('fault', { fault: 'OFFLINE', on: false });
    await until(() => driver().state === 'ONLINE', 10_000, 'online again');
    await sim.control('place', { mass: '0.500' });
    expect((await gateway.capture('TEST-BAL-01', 'GROSS')).outcome).toBe('CAPTURED');
  });

  it('a slow balance times out; the late answer is never taken for a later command', async () => {
    await sim.control('place', { mass: '3.000' });
    await new Promise((r) => setTimeout(r, 400));
    await sim.control('fault', { fault: 'SLOW', on: true });
    const r = await gateway.capture('TEST-BAL-01', 'GROSS', 500);
    expect(r).toMatchObject({ outcome: 'FAILED', error: 'DEVICE_OFFLINE' });
    await sim.control('fault', { fault: 'SLOW', on: false });
    await sim.control('add', { mass: '0.005' });
    await until(() => driver().state === 'ONLINE', 10_000, 'reconnect');
    const ok = await gateway.capture('TEST-BAL-01', 'GROSS');
    expect(ok.outcome).toBe('CAPTURED');
    if (ok.outcome === 'CAPTURED') expect(ok.reading.value).toBe('3.005');
  });

  it('[DI-20] a serial mismatch is refused at connect and alarmed; the heartbeat reports it; it clears when the right balance returns', async () => {
    await sim.control('fault', { fault: 'SERIAL_MISMATCH', on: true });
    // A reconnect is needed for I4 to be asked again.
    await sim.control('fault', { fault: 'OFFLINE', on: true });
    await sim.control('fault', { fault: 'OFFLINE', on: false });
    await until(() => driver().state === 'SERIAL_MISMATCH', 10_000, 'serial mismatch');
    const r = await gateway.capture('TEST-BAL-01', 'GROSS');
    expect(r).toMatchObject({ outcome: 'FAILED', error: 'SERIAL_MISMATCH' });
    expect(gateway.alarms.some((a) => a.kind === 'SERIAL_MISMATCH' && a.details['reported'] === 'SIM-9999')).toBe(true);
    await until(() => server.heartbeats.at(-1)?.devices[0]?.state === 'SERIAL_MISMATCH', 5000, 'a SERIAL_MISMATCH heartbeat');
    expect(server.heartbeats.at(-1)?.devices[0]?.serial).toBe('SIM-9999');
    await sim.control('fault', { fault: 'SERIAL_MISMATCH', on: false });
    await until(() => driver().state === 'ONLINE', 10_000, 'the right balance again');
  });

  it('[DI-31] a unit other than the configured one is refused and alarmed, never converted; a configuration that differs from the server binding captures nothing', async () => {
    const gServer = new FakeServer(keys.publicKeySpki);
    gServer.instruments = [{ deviceCode: 'TEST-BAL-01', serial: 'SIM-0001', unit: 'g', resolution: '0.001', roomCode: 'DISP-1' }];
    await gServer.start();
    const inGrams = { ...gateway.config, uplink: gServer.url, journalDir: tempDir(), devices: [{ ...gateway.config.devices[0]!, unit: 'g' }] };
    const other = await SiteGateway.start(inGrams, { driver: { commandTimeoutMs: 1000 }, manualUplink: true });
    const mismatched = await SiteGateway.start({ ...inGrams, uplink: server.url, journalDir: tempDir() }, { driver: { commandTimeoutMs: 1000 }, manualUplink: true });
    try {
      await other.uplink.logIn();
      await until(() => other.instruments.get('TEST-BAL-01')?.driver.state === 'ONLINE', 10_000, 'online');
      await sim.control('place', { mass: '1.000' });
      const r = await other.capture('TEST-BAL-01', 'GROSS');
      expect(r).toMatchObject({ outcome: 'FAILED', error: 'UNIT_MISMATCH', reading: null });
      expect(other.journal.lastSeq()).toBe(0n);
      expect(other.alarms.some((a) => a.kind === 'UNIT_MISMATCH')).toBe(true);

      await mismatched.uplink.logIn();
      await until(() => mismatched.instruments.get('TEST-BAL-01')?.driver.state === 'ONLINE', 10_000, 'online');
      expect(await mismatched.capture('TEST-BAL-01', 'GROSS')).toMatchObject({ outcome: 'FAILED', error: 'NOT_READY' });
      expect(mismatched.alarms.some((a) => a.kind === 'ENROLMENT_MISMATCH')).toBe(true);
    } finally {
      await other.stop();
      await mismatched.stop();
      await gServer.stop();
    }
  });

  it('live display: samples at about 4 Hz as decimal text, stable flag and status; OFFLINE while the balance is away', async () => {
    await sim.control('place', { mass: '1.250' });
    const samples: LiveSample[] = [];
    const stop = gateway.subscribeLive('TEST-BAL-01', (s) => samples.push(s));
    await new Promise((r) => setTimeout(r, 1300));
    expect(samples.length).toBeGreaterThanOrEqual(2);
    expect(samples.at(-1)).toMatchObject({ deviceCode: 'TEST-BAL-01', value: '1.250', unit: 'kg', stable: true, status: 'OK' });
    await sim.control('fault', { fault: 'OFFLINE', on: true });
    await until(() => samples.at(-1)?.status === 'OFFLINE', 5000, 'an OFFLINE sample');
    stop();
    await sim.control('fault', { fault: 'OFFLINE', on: false });
  });

  it('[DI-31] the API needs the token handed to the logged-in server; health shows no secret and, asked with a token, answers only the server\'s', async () => {
    const api = await startGatewayApi(gateway, { host: '127.0.0.1', port: 0 });
    try {
      const base = `http://127.0.0.1:${api.port}`;
      const health = (await (await fetch(`${base}/v1/health`)).json()) as { loggedIn: boolean };
      expect(health.loggedIn).toBe(true);
      expect(JSON.stringify(health)).not.toContain(gateway.apiToken);
      // The server's probe presents its API token (tablets 0320, P51): answered only for the right one.
      expect((await fetch(`${base}/v1/health`, { headers: { authorization: `Bearer ${gateway.apiToken}` } })).status).toBe(200);
      expect((await fetch(`${base}/v1/health`, { headers: { authorization: `Bearer ${'x'.repeat(43)}` } })).status).toBe(401);
      const denied = await fetch(`${base}/v1/devices/TEST-BAL-01/capture`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ purpose: 'GROSS' }) });
      expect(denied.status).toBe(401);
      expect(server.apiTokens).toContain(gateway.apiToken);
      await sim.control('place', { mass: '0.750' });
      const ok = await fetch(`${base}/v1/devices/TEST-BAL-01/capture`, {
        method: 'POST',
        headers: { 'content-type': 'application/json', authorization: `Bearer ${gateway.apiToken}` },
        body: JSON.stringify({ purpose: 'GROSS' }),
      });
      expect(ok.status).toBe(200);
      expect(((await ok.json()) as { outcome: string }).outcome).toBe('CAPTURED');
    } finally {
      await api.server.close();
    }
  });
});

apps/site-gateway/test/opcua-simulator.t.source:
/**
 * The OPC UA client driver on node-opcua against the OPC UA equipment simulator (slice 6b, builder A; DI-20, DI-31,
 * DI-32): SignAndEncrypt sessions reported with the certificate presented, native series of every unit, each fault of
 * the simulator alarmed, and a soak with the faults switched in turn proving that nothing is lost silently at the
 * gateway (every chunk numbered without a hole and valid; each interruption of a series alarmed; the feed reconciles
 * with itself).
 */
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { OpcuaEndpointSessionV1, SeriesChunkV1, shownValueProblem } from '@ebmr/integration-sdk/adapter';
import { liveDriver, SIM_UNITS, startOpcuaSimulator, type LiveRig, type OpcuaSimProcess } from './opcua-support.ts';
import { until } from './support.ts';

let sim: OpcuaSimProcess;
beforeAll(async () => {
  sim = await startOpcuaSimulator();
}, 90_000);
afterAll(async () => {
  await sim?.stop();
});

const chunksOf = (r: LiveRig) => r.feed.published().filter((m) => m.messageType === 'opcua.series_chunk').map((m) => SeriesChunkV1.parse(m.payload));

describe('the OPC UA driver against the simulator', () => {
  it('[DI-20][DI-32] a SignAndEncrypt session with the enrolled certificate, reported first; native series of every unit; the process view shows each raw value exactly', async () => {
    const r = liveDriver(sim);
    try {
      await until(() => r.driver.state === 'ONLINE', 30_000, 'online');
      const first = r.feed.published()[0];
      expect(OpcuaEndpointSessionV1.parse(first?.payload)).toMatchObject({ certificateThumbprint: sim.thumbprint, reportedLocation: 'RM-COMP-1', securityMode: 'SignAndEncrypt' });
      await until(() => new Set(chunksOf(r).map((c) => c.subjectCode)).size === Object.keys(SIM_UNITS).length, 20_000, 'a chunk of every unit');
      for (const unit of Object.keys(SIM_UNITS)) {
        const v = await r.driver.unit(unit).read();
        if (!v.ok) throw new Error(`${unit} not readable`);
        expect(v.sample.values.length, unit).toBeGreaterThan(0);
        for (const x of v.sample.values) {
          const n = v.native.values[x.tag];
          expect(n, `${unit}/${x.tag}`).toBeDefined();
          expect(shownValueProblem(n?.raw ?? '', x.value), `${unit}/${x.tag}`).toBeNull();
        }
      }
      // A setpoint download is written and read back from the device.
      expect(await r.driver.unit('PRESS-01').write('force.main_kN', '13.50')).toEqual({ ok: true });
      const after = await r.driver.unit('PRESS-01').read();
      if (!after.ok) throw new Error('not readable');
      expect(after.sample.setpoints.find((s) => s.tag === 'force.main_kN')?.value).toBe('13.5');
    } finally {
      await r.stop();
    }
  }, 90_000);

  it('[DI-31] OPC UA feed gap, stale value and recipe mismatch each alarm; a cut link, an older sample, a unit not served and a reject burst too', async () => {
    const r = liveDriver(sim, { gapAfterMs: 1500 });
    const kinds = () => new Set(r.alarms.map((a) => a.kind));
    try {
      await until(() => r.driver.state === 'ONLINE', 30_000, 'online');
      await sim.fault('FEED_GAP', true);
      await until(() => kinds().has('FEED_GAP'), 10_000, 'feed gap alarm');
      await sim.fault('FEED_GAP', false);
      await sim.fault('STALE_VALUE', true);
      await until(() => kinds().has('STALE_VALUE'), 10_000, 'stale alarm');
      await sim.fault('STALE_VALUE', false);
      const v = await r.driver.unit('PRESS-01').read();
      if (!v.ok) throw new Error('not readable');
      r.driver.expectRecipe('PRESS-01', 'RCP-1');
      await sim.fault('RECIPE_MISMATCH', true);
      await until(() => kinds().has('RECIPE_MISMATCH'), 10_000, 'recipe mismatch alarm');
      expect(r.feed.published().some((m) => m.messageType === 'opcua.equipment_event' && (m.payload as { kind: string }).kind === 'RECIPE_MISMATCH')).toBe(true);
      await sim.fault('RECIPE_MISMATCH', false);
      // OUT_OF_ORDER is one sample per unit, once. The server samples each variable at its sampling interval, so under
      // load the next regular sample can replace the older one before it is sampled (OPC UA sampling, not a loss in the
      // driver): the fault is fired again, at most once a second, until the driver has seen one.
      let fired = 0;
      await until(async () => {
        if (kinds().has('OUT_OF_ORDER')) return true;
        if (performance.now() - fired > 1000) {
          fired = performance.now();
          await sim.fault('OUT_OF_ORDER', true);
        }
        return false;
      }, 15_000, 'out-of-order alarm');
      await sim.fault('WRONG_BATCH', true);
      await until(() => kinds().has('WRONG_UNIT'), 10_000, `wrong unit alarm ${JSON.stringify([...kinds()])} ${JSON.stringify(r.alarms.slice(-3))}`);
      await sim.fault('REJECT_BURST', true);
      await until(() => r.feed.published().some((m) => m.messageType === 'opcua.alarm'), 10_000, 'reject burst in the feed');
      await sim.fault('REJECT_BURST', false);
      const sessions = () => r.feed.published().filter((m) => m.messageType === 'opcua.endpoint_session').length;
      await sim.fault('LINK_CUT', true);
      await until(() => kinds().has('DISCONNECTED') && r.driver.state === 'ONLINE' && sessions() === 2, 30_000, 'reconnected after the cut');
    } finally {
      await r.stop();
    }
  }, 180_000);

  it('[DI-31] soak: faults in turn; every chunk numbered without a hole and valid, each interruption alarmed, the feed reconciles; no silent loss', async () => {
    const r = liveDriver(sim, { gapAfterMs: 1500, chunkMaxSpanUs: 1_000_000n });
    try {
      await until(() => r.driver.state === 'ONLINE', 30_000, 'online');
      const startUs = BigInt(Date.now()) * 1000n;
      for (const f of ['FEED_GAP', 'STALE_VALUE', 'OUT_OF_ORDER', 'LINK_CUT', 'WRONG_BATCH', 'DRIFT', 'EXCURSION']) {
        await sim.fault(f, true);
        await new Promise((res) => setTimeout(res, 2500));
        await sim.fault(f, false);
        await until(() => r.driver.state === 'ONLINE', 30_000, `online after ${f}`);
        await new Promise((res) => setTimeout(res, 800));
      }
      await r.driver.stop();
      const chunks = chunksOf(r);
      const byTag = new Map<string, SeriesChunkV1[]>();
      for (const c of chunks) byTag.set(`${c.subjectCode}|${c.tag}`, [...(byTag.get(`${c.subjectCode}|${c.tag}`) ?? []), c]);
      expect(byTag.size).toBeGreaterThan(20);
      // Each fault that interrupts or spoils a series was alarmed.
      expect(new Set(r.alarms.map((a) => a.kind))).toEqual(expect.objectContaining({}));
      for (const k of ['FEED_GAP', 'DISCONNECTED', 'STALE_VALUE', 'OUT_OF_ORDER', 'WRONG_UNIT']) expect(r.alarms.some((a) => a.kind === k), k).toBe(true);
      for (const [key, list] of byTag) {
        // Chunk numbers 1..n without a hole; source times strictly increasing across chunks.
        expect(list.map((c) => c.chunkNo), key).toEqual(list.map((_, i) => String(i + 1)));
        const times = list.flatMap((c) => c.samples.map((s) => BigInt(s.sourceTime)));
        for (let i = 1; i < times.length; i++) expect(times[i]! > times[i - 1]!, key).toBe(true);
      }
      // The feed: every message once, in sequence; its reconciliation over the whole period counts every message.
      const all = r.feed.published();
      expect(all.map((m) => m.sequenceNo)).toEqual(all.map((_, i) => String(i + 1)));
      expect(new Set(all.map((m) => m.idempotencyKey)).size).toBe(all.length);
      const rec = r.feed.reconciliation(0n, startUs + 3_600_000_000_000n);
      expect(rec.sourceCount).toBe(String(all.length));
    } finally {
      await r.stop();
    }
  }, 240_000);

  it('[DI-20] a certificate change: the session is reported with the new certificate, the driver refuses it and reads nothing', async () => {
    const r = liveDriver(sim);
    try {
      await until(() => r.driver.state === 'ONLINE', 30_000, 'online');
      const { certificateThumbprint } = await sim.fault('CERTIFICATE_CHANGE', true);
      expect(certificateThumbprint).not.toBe(sim.thumbprint);
      await until(() => r.driver.state === 'CERTIFICATE_MISMATCH', 30_000, 'certificate mismatch');
      expect(r.alarms.some((a) => a.kind === 'CERTIFICATE_MISMATCH')).toBe(true);
      const sessions = r.feed.published().filter((m) => m.messageType === 'opcua.endpoint_session').map((m) => (m.payload as { certificateThumbprint: string }).certificateThumbprint);
      expect(sessions).toEqual([sim.thumbprint, certificateThumbprint]);
      expect(await r.driver.unit('PRESS-01').read()).toMatchObject({ ok: false });
      sim.thumbprint = certificateThumbprint;
    } finally {
      await r.stop();
    }
  }, 120_000);
});

apps/site-gateway/test/device-config.tes.source:
/**
 * Phase 3 slice 6c (D-S6-8): the gateway's device configuration takes every kind of process equipment a simulator
 * speaks, and the IPC and packaging instruments on the scale protocol, each in a unit of its kind.
 */
import { describe, expect, it } from 'vitest';
import { PROCESS_EQUIPMENT_KINDS } from '@ebmr/integration-sdk/process';
import { INSTRUMENT_KINDS, INSTRUMENT_PROFILES } from '@ebmr/integration-sdk/scale';
import { GatewayConfigFile } from '../src/config.ts';

const base = { gatewayCode: 'TEST-GW-01', installation: 'SANDBOX', listen: '127.0.0.1:0', uplink: 'http://127.0.0.1:1', keyFile: 'k', serviceKeysFile: 's', journalDir: 'j' };
const balance = { code: 'TEST-BAL-01', driver: 'mt-sics', host: '127.0.0.1', port: 1, expectedSerial: 'SIM-0001', resolution: '0.001', unit: 'kg' };

describe('gateway device configuration (slice 6c, D-S6-8)', () => {
  it('[DI-31] every kind of process equipment is accepted behind the simulator driver; an unknown kind is refused', () => {
    const processDevices = PROCESS_EQUIPMENT_KINDS.map((equipment, i) => ({
      code: `TEST-${equipment.replace(/_/g, '-')}-01`,
      driver: 'process-sim',
      equipment,
      host: '127.0.0.1',
      port: 4100 + i,
      expectedSerial: `${equipment.replace(/_/g, '-')}-0001`,
    }));
    expect(GatewayConfigFile.safeParse({ ...base, devices: [balance], processDevices }).success).toBe(true);
    expect(GatewayConfigFile.safeParse({ ...base, devices: [balance], processDevices: [{ ...processDevices[0], equipment: 'TOASTER' }] }).success).toBe(false);
  });

  it('[DI-31][PR-20] the IPC and packaging instruments are accepted on the scale protocol in a unit of their kind; another unit is refused, naming the device', () => {
    const devices = INSTRUMENT_KINDS.map((instrument, i) => ({
      ...balance,
      code: `TEST-${instrument.replace(/_/g, '-')}-01`,
      instrument,
      port: 4200 + i,
      expectedSerial: `SIM-${String(100 + i)}`,
      resolution: INSTRUMENT_PROFILES[instrument].resolution,
      unit: INSTRUMENT_PROFILES[instrument].units[0],
    }));
    expect(GatewayConfigFile.safeParse({ ...base, devices }).success).toBe(true);
    // A device without a kind is a balance, as before slice 6c.
    expect(GatewayConfigFile.safeParse({ ...base, devices: [balance] }).success).toBe(true);
    const wrong = GatewayConfigFile.safeParse({ ...base, devices: [{ ...balance, code: 'TEST-HT-01', instrument: 'HARDNESS_TESTER', unit: 'kg' }] });
    expect(wrong.success).toBe(false);
    expect(JSON.stringify(wrong.error?.issues)).toMatch(/TEST-HT-01: a hardness tester reports breaking force of one tablet in N or kp, not in kg/);
    expect(GatewayConfigFile.safeParse({ ...base, devices: [{ ...balance, unit: 'pct' }] }).success).toBe(false);
  });
});

apps/site-gateway/test/opcua-driver-shap.source:
/**
 * The OPC UA driver's fixed shape (Phase 6 slice 6b-0): the endpoint certificate check (DI-20, D-P6b-2) and the series
 * chunker whose chunks the database accepts (numbered, hashed, cut by samples or span; DI-32).
 */
import { SeriesChunkV1 } from '@ebmr/integration-sdk/adapter';
import { describe, expect, it } from 'vitest';
import { certificateProblem, SeriesChunker } from '../src/drivers/opcua.ts';

const endpoint = { endpointUrl: 'opc.tcp://press-01:4840/ua', securityMode: 'SignAndEncrypt', securityPolicy: 'Basic256Sha256', certificateThumbprint: 'a'.repeat(64), equipmentCodes: ['PRESS-01'], areaCode: 'RM-COMP-1' };

describe('OPC UA driver shape (6b-0)', () => {
  it('[DI-20] an endpoint whose certificate is not the enrolled one, or that is not SignAndEncrypt, is refused', () => {
    expect(certificateProblem(endpoint, 'a'.repeat(64))).toBeNull();
    expect(certificateProblem(endpoint, 'b'.repeat(64))).toMatch(/certificate changed/);
    expect(certificateProblem({ ...endpoint, securityMode: 'None' }, 'a'.repeat(64))).toMatch(/not enrolled for SignAndEncrypt/);
  });

  it('[DI-32] the chunker numbers its chunks, cuts them by sample count or span, and each chunk is one the contract accepts', () => {
    const c = new SeriesChunker({ kind: 'EQUIPMENT', code: 'PRESS-01' }, 'force.main_kN', 'kN', 7n, 3, 1_000_000n);
    const s = (us: bigint, raw: string) => ({ sourceTime: us.toString(), serverTime: null, raw, value: raw, status: '0x00000000' });
    const out = [c.add(s(1n, '12.5')), c.add(s(2n, '12.6')), c.add(s(3n, '12.7')), c.add(s(4n, '12.8')), c.add(s(2_000_000n, '12.9')), c.flush(), c.flush()];
    const chunks = out.filter((x) => x !== null);
    expect(chunks.map((x) => [x.chunkNo, x.samples.length])).toEqual([['7', 3], ['8', 1], ['9', 1]]);
    for (const x of chunks) expect(SeriesChunkV1.safeParse(x).success).toBe(true);
  });
});
